#pragma once

#include <chrono>
#include <string>

namespace UICommon::EmuBank
{
enum class PairingState
{
  Idle,
  Waiting,
  Ready,
  Failed,
};

struct PairingStartResult
{
  std::string approval_url;
  std::string error;

  explicit operator bool() const { return !approval_url.empty() && error.empty(); }
};

void Init();
void Shutdown();

// Starts secure browser-based device authorization. The persistent device secret is generated by
// Dolphin and never sent to or exposed by the browser.
PairingStartResult BeginPairing(std::string server_url, std::string device_name,
                                std::string platform);
PairingState GetPairingState();
// Returns the browser approval URL for an in-progress request so a recreated frontend can resume
// authorization. This URL does not contain Dolphin's persistent device credential.
std::string GetPairingApprovalUrl();

// Commits an approved pairing to Dolphin's base configuration. Call from the frontend/UI thread.
bool FinalizePairing();

// Requests a background sync. Downloads are deferred automatically while emulation is active.
void RequestSync();

// Requests a fresh stopped-emulation sync and waits up to the supplied bound for that request to
// finish. This is intended for orderly frontend shutdown paths, not UI threads.
bool SyncAndWait(std::chrono::milliseconds timeout);

// A short, human-readable status suitable for settings UIs. Credentials are never included.
std::string GetStatus();
}  // namespace UICommon::EmuBank
